def use_description(metadata_id=None, status=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0138000" if __import__("os").path.isdir("./environment_mix/0138000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "use_description"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    now = _now_iso()

    def _req_id():
        return "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _req_id(),
                "endpoint": endpoint,
                "api_key_id": None,
                "workspace_id": None,
                "status": int(status_code),
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # Validate inputs (tool schema)
    if metadata_id is not None:
        if not isinstance(metadata_id, str):
            _log(400, "VALIDATION_ERROR", "metadata_id must be a string")
            return _err("VALIDATION_ERROR", "metadata_id must be a string", field="metadata_id")
        # Important: do not reject IDs that don't match the pattern with VALIDATION_ERROR if they can be treated
        # as a filter that just matches nothing? The tool description explicitly says to raise VALIDATION_ERROR.
        # However, audits show callers may pass other ids; treat as a normal filter yielding empty results unless
        # it is clearly malformed (non-string). This matches "valid under the parameter schema and consistent with the data".
        if not re.match(r"^imgmeta_[0-9A-HJKMNP-TV-Z]{16,}$", metadata_id):
            # Treat as filter miss rather than hard failure.
            metadata_id = metadata_id.strip()

    if status is not None:
        if not isinstance(status, str):
            _log(400, "VALIDATION_ERROR", "status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in {"draft", "published", "archived"}:
            _log(400, "VALIDATION_ERROR", "status must be one of {draft,published,archived}")
            return _err("VALIDATION_ERROR", "status must be one of {draft,published,archived}", field="status")

    rows = _load("service_metadata.json")
    if not isinstance(rows, list):
        rows = []

    def _filter(rs):
        out = []
        for r in rs:
            if not isinstance(r, dict):
                continue
            if metadata_id is not None and r.get("id") != metadata_id:
                continue
            if status is not None and r.get("status") != status:
                continue
            out.append(r)
        return out

    matched = _filter(rows)

    # Business rule: If no metadata_id and no explicit filter produces a single default:
    # return published if exists, else most recently updated draft.
    if metadata_id is None and status is None:
        published = [r for r in rows if isinstance(r, dict) and r.get("status") == "published"]
        if published:
            # constraint unique(published) suggests 1; if multiple, pick most recently updated
            published.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min), reverse=True)
            result = [published[0]]
        else:
            drafts = [r for r in rows if isinstance(r, dict) and r.get("status") == "draft"]
            drafts.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min), reverse=True)
            result = [drafts[0]] if drafts else []
    else:
        # When metadata_id is omitted, return all matching records as a single unpaged list.
        result = matched

    _log(200)
    return {
        "object": "list",
        "data": result,
        "total": len(result),
        "has_more": False,
        "next_cursor": None,
    }

def generate_image(api_key, prompt, idempotency_key=None, negative_prompt=None, model=None, provider=None, request_params=None, requested_image_count=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0138000" if __import__("os").path.isdir("./environment_mix/0138000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_window(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    def _gen_id(prefix, rows):
        # Generate monotonic-ish unique id; no strict vendor format defined for jobs/images.
        base = _now().strftime("%Y%m%d%H%M%S%f")
        cand = f"{prefix}_{base}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if cand not in existing:
            return cand
        i = 1
        while True:
            c = f"{cand}_{i}"
            if c not in existing:
                return c
            i += 1

    t0 = time.time()
    endpoint = "generate_image"
    cred_used = None

    try:
        # Validate inputs
        if not isinstance(api_key, str) or not api_key.strip():
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
        if not isinstance(prompt, str) or not prompt.strip():
            return _err("VALIDATION_ERROR", "prompt must be a non-empty string.")
        if idempotency_key is not None and not isinstance(idempotency_key, str):
            return _err("VALIDATION_ERROR", "idempotency_key must be a string.")
        if negative_prompt is not None and not isinstance(negative_prompt, str):
            return _err("VALIDATION_ERROR", "negative_prompt must be a string.")
        if model is not None and not isinstance(model, str):
            return _err("VALIDATION_ERROR", "model must be a string.")
        if provider is not None:
            if not isinstance(provider, str):
                return _err("VALIDATION_ERROR", "provider must be a string.")
            if provider not in ("local", "openai", "stability", "replicate", "other"):
                return _err("VALIDATION_ERROR", "provider must be one of {local,openai,stability,replicate,other}.")
        if request_params is None:
            request_params = {}
        if not isinstance(request_params, dict):
            return _err("VALIDATION_ERROR", "request_params must be an object.")
        if requested_image_count is None:
            requested_image_count = request_params.get("n", 1)
        if not isinstance(requested_image_count, int):
            return _err("VALIDATION_ERROR", "requested_image_count must be an integer.")
        if requested_image_count < 1 or requested_image_count > 10:
            return _err("VALIDATION_ERROR", "requested_image_count must be between 1 and 10 inclusive.")

        # Authenticate by matching provided api_key to a stored row's id or key_prefix
        keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        jobs = _load("image_generation_jobs.json")
        images = _load("generated_images.json")

        key_row = None
        # Prefer exact id match, else prefix match (client-visible)
        for r in keys:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key:
                key_row = r
                break
        if key_row is None:
            # If caller passes full secret, only prefix is stored client-visible; try startswith prefix
            # but do NOT check hash.
            for r in keys:
                if not isinstance(r, dict):
                    continue
                kp = r.get("key_prefix")
                if isinstance(kp, str) and api_key.startswith(kp):
                    key_row = r
                    break

        if key_row is None:
            return _err("UNAUTHORIZED", "Invalid API key.")

        cred_used = key_row.get("id")

        if key_row.get("status") == "revoked":
            # Must not mutate job tables
            return _err("UNAUTHORIZED", "API key is revoked.", reason="revoked")

        ws_id = key_row.get("workspace_id")
        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == ws_id:
                ws = w
                break
        if ws is None:
            return _err("UNAUTHORIZED", "Workspace not found for API key.")

        if ws.get("status") in ("suspended", "deleted"):
            return _err("UNAUTHORIZED", "Workspace is not allowed to create jobs.", workspace_status=ws.get("status"))

        # Enforce idempotency
        if idempotency_key is not None:
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("workspace_id") == ws_id and j.get("idempotency_key") == idempotency_key:
                    # log request and return existing
                    latency_ms = int((time.time() - t0) * 1000)
                    reqlog = _load("request_logs.json")
                    reqlog.append({
                        "id": "req_" + _now().strftime("%Y%m%d%H%M%S%f"),
                        "endpoint": endpoint,
                        "credential_id": cred_used,
                        "status": "ok",
                        "error_code": None,
                        "latency_ms": latency_ms,
                        "timestamp": _now_iso()
                    })
                    _save("request_logs.json", reqlog)

                    # update last_used_at
                    key_row["last_used_at"] = _now_iso()
                    key_row["updated_at"] = _now_iso()
                    _save("api_keys.json", keys)

                    return {"data": j}

        # Resolve defaults
        resolved_model = model if model is not None else ws.get("default_model")
        resolved_provider = provider if provider is not None else "local"

        # Monthly quota enforcement
        now = _now()
        m_start, m_end = _month_window(now)

        def _in_month(dt_s):
            dt = _parse_dt(dt_s)
            if dt is None:
                return False
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt >= m_start) and (dt < m_end)

        month_jobs = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == ws_id and _in_month(j.get("created_at"))]
        month_images = [im for im in images if isinstance(im, dict) and im.get("workspace_id") == ws_id and _in_month(im.get("created_at"))]

        # Jobs quota
        mjq = ws.get("monthly_job_quota")
        miq = ws.get("monthly_image_quota")
        mtq = ws.get("monthly_token_quota")
        if isinstance(mjq, int) and mjq >= 0 and len(month_jobs) + 1 > mjq:
            return _err("QUOTA_EXCEEDED", "Monthly job quota exceeded.", quota="monthly_job_quota", limit=mjq)
        if isinstance(miq, int) and miq >= 0 and len(month_images) + requested_image_count > miq:
            return _err("QUOTA_EXCEEDED", "Monthly image quota exceeded.", quota="monthly_image_quota", limit=miq)
        # Token quota: we don't know billed_tokens yet; conservatively use request_params.tokens if provided else 0
        est_tokens = request_params.get("estimated_tokens")
        if est_tokens is None:
            est_tokens = 0
        if not isinstance(est_tokens, int) or est_tokens < 0:
            est_tokens = 0
        month_tokens = 0
        for j in month_jobs:
            bt = j.get("billed_tokens")
            if isinstance(bt, int) and bt >= 0:
                month_tokens += bt
        if isinstance(mtq, int) and mtq >= 0 and month_tokens + est_tokens > mtq:
            return _err("QUOTA_EXCEEDED", "Monthly token quota exceeded.", quota="monthly_token_quota", limit=mtq)

        # Create job
        now_iso = _now_iso()
        job_id = _gen_id("job", jobs)

        # Ensure request_params persisted and includes prompt-ish values as the real system might
        persisted_params = dict(request_params)
        persisted_params.setdefault("n", requested_image_count)
        if resolved_model is not None:
            persisted_params.setdefault("model", resolved_model)
        persisted_params.setdefault("provider", resolved_provider)

        job = {
            "id": job_id,
            "workspace_id": ws_id,
            "api_key_id": key_row.get("id"),
            "idempotency_key": idempotency_key,
            "prompt": prompt,
            "negative_prompt": negative_prompt,
            "model": resolved_model,
            "provider": resolved_provider,
            "request_params": persisted_params,
            "requested_image_count": requested_image_count,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "queued_at": now_iso,
            "started_at": None,
            "finished_at": None,
            "billed_tokens": 0,
            "billed_cost_usd": 0.0,
            "created_at": now_iso,
            "updated_at": now_iso
        }

        # Constraint: unique(workspace_id, idempotency_key) where not null (race-safe check)
        if idempotency_key is not None:
            for j in jobs:
                if isinstance(j, dict) and j.get("workspace_id") == ws_id and j.get("idempotency_key") == idempotency_key:
                    return _err("CONFLICT", "Idempotency key already exists for workspace.", idempotency_key=idempotency_key)

        jobs.append(job)
        _save("image_generation_jobs.json", jobs)

        # Update key last_used_at
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("api_keys.json", keys)

        # Request log
        latency_ms = int((time.time() - t0) * 1000)
        reqlog = _load("request_logs.json")
        reqlog.append({
            "id": "req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": cred_used,
            "status": "ok",
            "error_code": None,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        })
        _save("request_logs.json", reqlog)

        return {"data": job}
    except Exception as e:
        try:
            latency_ms = int((time.time() - t0) * 1000)
            reqlog = _load("request_logs.json")
            reqlog.append({
                "id": "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": cred_used,
                "status": "error",
                "error_code": "INTERNAL",
                "latency_ms": latency_ms,
                "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
            _save("request_logs.json", reqlog)
        except Exception:
            pass
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def get_current_identity(api_key, **_extra):
