def list_image_generation_jobs(api_key, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0138000" if __import__("os").path.isdir("./environment_mix/0138000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_key(r):
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    def _encode_cursor(dt, job_id):
        payload = f"{dt.isoformat()}|{job_id}"
        return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii")

    def _decode_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("ascii")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return None
            dt = _parse_dt(parts[0])
            if dt is None:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt, parts[1])
        except Exception:
            return None

    t0 = time.time()
    endpoint = "list_image_generation_jobs"
    cred_used = None

    try:
        # Validation
        if not isinstance(api_key, str) or not api_key.strip():
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
        if status is not None:
            if not isinstance(status, str):
                return _err("VALIDATION_ERROR", "status must be a string.")
            if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
                return _err("VALIDATION_ERROR", "status must be one of {queued,running,succeeded,failed,cancelled}.")
        ca = None
        cb = None
        if created_after is not None:
            if not isinstance(created_after, str):
                return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
            ca = _parse_dt(created_after)
            if ca is None:
                return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
            if ca.tzinfo is None:
                ca = ca.replace(tzinfo=datetime.timezone.utc)
        if created_before is not None:
            if not isinstance(created_before, str):
                return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.")
            cb = _parse_dt(created_before)
            if cb is None:
