        rows = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == ws_id]
        if status is not None:
            rows = [j for j in rows if j.get("status") == status]
        if ca is not None:
            rows = [j for j in rows if (_dt_key(j) >= ca)]
        if cb is not None:
            rows = [j for j in rows if (_dt_key(j) < cb)]

        # Order by created_at desc, then id desc for stability
        rows.sort(key=lambda r: (_dt_key(r), str(r.get("id") or "")), reverse=True)

        # Apply cursor (created_at,id) boundary, exclusive
        if cursor:
            dec = _decode_cursor(cursor)
            if dec is None:
