            cdt, cid = dec
            filtered = []
            for r in rows:
                rdt = _dt_key(r)
                rid = str(r.get("id") or "")
                # Since sorted desc: include those strictly "before" the cursor (older or same time but smaller id)
                if (rdt < cdt) or (rdt == cdt and rid < cid):
                    filtered.append(r)
            rows = filtered

        total = len(rows)
        page = rows[:limit]
        has_more = total > len(page)
        next_cursor = None
        if has_more and page:
            last = page[-1]
