            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _as_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("get_image_generation_job", None, None, 400, "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(job_id, str) or not re.match(r"^imgjob_[0-9A-HJKMNP-TV-Z]{16,}$", job_id):
        _log("get_image_generation_job", None, None, 400, "VALIDATION_ERROR", "job_id is invalid")
        return _err("VALIDATION_ERROR", "job_id is invalid", field="job_id")

    # Authenticate api_key: match by id, key_prefix, or hash(plaintext) against key_hash
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

