        cands = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == v:
                cands.append(k)
                continue
            if isinstance(k.get("key_prefix"), str) and v.startswith(k["key_prefix"]):
                cands.append(k)
                continue
        # also try hashing the provided plaintext
        hv = hashlib.sha256(v.encode("utf-8")).hexdigest()
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("key_hash") == hv and k not in cands:
                cands.append(k)
        return cands

    key_rows = _find_key(api_key)
    if not key_rows:
        _log("get_image_generation_job", None, None, 401, "UNAUTHORIZED", "Invalid api_key")
        return _err("UNAUTHORIZED", "Invalid api_key")

    # pick a key whose workspace exists
    chosen = None
    ws = None
    for k in key_rows:
        wid = k.get("workspace_id")
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wid), None)
        if ws_row is not None:
            chosen = k
            ws = ws_row
            break
    if chosen is None:
        _log("get_image_generation_job", None, None, 401, "UNAUTHORIZED", "Invalid api_key")
        return _err("UNAUTHORIZED", "Invalid api_key")

    if chosen.get("status") == "revoked":
