        return _err("UNAUTHORIZED", "API key is revoked")

    # update last_used_at
    changed = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == chosen.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            changed = True
            break
    if changed:
        _save("api_keys.json", keys)

    jobs = _load("image_generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id and j.get("workspace_id") == ws.get("id")), None)
