    def _log(status_code, api_key_id=None, workspace_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _req_id(),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": int(status_code),
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(400, None, None, "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    api_key_val = api_key.strip()

    if not isinstance(job_id, str) or not re.match(r"^imgjob_[0-9A-HJKMNP-TV-Z]{16,}$", job_id):
        _log(400, None, None, "VALIDATION_ERROR", "job_id does not match required pattern")
        return _err("VALIDATION_ERROR", "job_id does not match required pattern", field="job_id")

    # Reason: accept strings; if callers pass non-string, coerce to string (audits show numeric passed)
    if reason is not None:
        if isinstance(reason, str):
            reason_str = reason
        else:
            reason_str = str(reason)
        if len(reason_str) > 500:
            _log(400, None, None, "VALIDATION_ERROR", "reason too long")
            return _err("VALIDATION_ERROR", "reason too long", field="reason")
        reason = reason_str

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    jobs = _load("image_generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Authenticate: match by id OR by key_prefix (client-visible). Never by key_hash.
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_val or k.get("key_prefix") == api_key_val:
            key_row = k
            break
    if not key_row:
        _log(401, None, None, "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        _log(401, key_row.get("id"), key_row.get("workspace_id"), "UNAUTHORIZED", "API key is revoked")
        return _err("UNAUTHORIZED", "API key is revoked")

    workspace_id = key_row.get("workspace_id")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if not ws or ws.get("status") != "active":
        _log(401, key_row.get("id"), workspace_id, "UNAUTHORIZED", "Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Find job visible to caller workspace
    job = None
    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id and j.get("workspace_id") == workspace_id:
            job = j
            job_idx = i
            break
    if job is None:
        _log(404, key_row.get("id"), workspace_id, "NOT_FOUND", "Job not found")
        return _err("NOT_FOUND", "Job not found")

    # Enforce lifecycle / conflicts
    terminal = {"succeeded", "failed", "cancelled"}
    if job.get("status") in terminal:
        _log(409, key_row.get("id"), workspace_id, "CONFLICT", "Job is already terminal")
        return _err("CONFLICT", "Job is already terminal")

    if job.get("status") not in {"queued", "running"}:
        _log(409, key_row.get("id"), workspace_id, "INVALID_TRANSITION", "Job cannot be cancelled from current status")
        return _err("INVALID_TRANSITION", "Job cannot be cancelled from current status", from_status=job.get("status"), to_status="cancelled")

    # Mutate
    jobs[job_idx]["status"] = "cancelled"
    jobs[job_idx]["finished_at"] = now
    jobs[job_idx]["updated_at"] = now
    jobs[job_idx]["error_code"] = "user_cancelled"
    if reason:
        jobs[job_idx]["error_message"] = f"Cancelled by client: {reason}"
    else:
        jobs[job_idx]["error_message"] = "Cancelled by client request before completion."

    _save("image_generation_jobs.json", jobs)

    # Update last_used_at (best-effort, but must persist if changed)
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            keys[i]["last_used_at"] = now
            keys[i]["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _log(200, key_row.get("id"), workspace_id)
    return {"object": "image_generation_job", "data": jobs[job_idx]}

