                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": int(status_code),
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # Validate inputs (pattern in schema), but do not block legitimate requests by over-validating:
    # if it's a string, treat mismatched pattern as a normal NOT_FOUND later (audits show wrong-id was passed).
    if not isinstance(api_key, str) or not api_key.strip():
        _log(400, None, None, "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    api_key_val = api_key.strip()

    if not isinstance(image_id, str) or not image_id.strip():
        _log(400, None, None, "VALIDATION_ERROR", "image_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "image_id must be a non-empty string", field="image_id")
    image_id_val = image_id.strip()

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    images = _load("generated_images.json")
    if not isinstance(images, list):
        images = []

    # Authenticate: match by id OR by key_prefix
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_val or k.get("key_prefix") == api_key_val:
            key_row = k
            break
    if not key_row:
        _log(401, None, None, "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        _log(401, key_row.get("id"), key_row.get("workspace_id"), "UNAUTHORIZED", "API key is revoked")
        return _err("UNAUTHORIZED", "API key is revoked")

    workspace_id = key_row.get("workspace_id")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if not ws or ws.get("status") != "active":
        _log(401, key_row.get("id"), workspace_id, "UNAUTHORIZED", "Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Find image in caller workspace
    img = None
    img_idx = None
    for i, im in enumerate(images):
        if isinstance(im, dict) and im.get("id") == image_id_val and im.get("workspace_id") == workspace_id:
            img = im
            img_idx = i
            break
    if img is None:
        _log(404, key_row.get("id"), workspace_id, "NOT_FOUND", "Image not found")
        return _err("NOT_FOUND", "Image not found")

    if img.get("status") == "deleted":
        _log(409, key_row.get("id"), workspace_id, "CONFLICT", "Image is already deleted")
        return _err("CONFLICT", "Image is already deleted")

    if img.get("status") != "stored":
        _log(409, key_row.get("id"), workspace_id, "INVALID_TRANSITION", "Image cannot be deleted from current status")
        return _err("INVALID_TRANSITION", "Image cannot be deleted from current status", from_status=img.get("status"), to_status="deleted")

    # Mutate: soft-delete
    images[img_idx]["status"] = "deleted"
    images[img_idx]["updated_at"] = now
    _save("generated_images.json", images)

    # Update last_used_at
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            keys[i]["last_used_at"] = now
            keys[i]["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _log(200, key_row.get("id"), workspace_id)
    return {"object": "generated_image", "data": images[img_idx]}
